import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
patterns=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Reconstruct the 5x5 outlined tiles visible in the input (the fifth row/column is clipped).
for tr,rs in enumerate(starts):
  for tc,cs in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=rs+dr,cs+dc
        if r<n and c<n:
          g[r][c]=4 if dr in (0,4) or dc in (0,4) else patterns[tr][tc]
# Join repeated non-background tile colors through the blank gutters.
# Color 3: tile centers rows 0,2 and cols 0,3.
centers=[3,10,17,24]
for r in (centers[0], centers[2]):
  for c in (6,7,13,14,20,21): g[r][c]=3
for c in (centers[0], centers[3]):
  for r in (6,7,13,14): g[r][c]=3
# Color 8: tile centers rows 1,3 and cols 1,2.
for r in (centers[1], centers[3]):
  for c in (13,14): g[r][c]=8
for c in (centers[1], centers[2]):
  for r in (13,14,20,21): g[r][c]=8
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))

